def solve():
    from z3 import Bool, Solver, Or, Not, And, Sum, If, sat

    n = 23
    E = [[Bool(f"e_{i}_{j}") for j in range(n)] for i in range(n)]

    s = Solver()

    # Undirected graph, no self loops
    for i in range(n):
        s.add(Not(E[i][i]))
        for j in range(i+1, n):
            s.add(E[i][j] == E[j][i])

    # Degree between 4 and 5
    for i in range(n):
        deg = Sum([If(E[i][j], 1, 0) for j in range(n)])
        s.add(deg >= 4)
        s.add(deg <= 5)

    # Girth >= 6 means no cycles of length 3, 4, 5
    # No 3-cycles
    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                s.add(Not(And(E[i][j], E[j][k], E[k][i])))

    # No 4-cycles
    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                for l in range(k+1, n):
                    # permutations of 4 vertices: 3 distinct 4-cycles
                    s.add(Not(And(E[i][j], E[j][k], E[k][l], E[l][i])))
                    s.add(Not(And(E[i][j], E[j][l], E[l][k], E[k][i])))
                    s.add(Not(And(E[i][k], E[k][j], E[j][l], E[l][i])))

    # No 5-cycles
    # Just use a simple path approach for 5-cycles to avoid writing all permutations
    # Actually, z3 might be slow for 5-cycles. Let's just check if it's unsat even without 5-cycles?
    # Wait, Moore bound for girth 5 is d^2+1 = 17. So girth 5 is possible for n=23.
    # We need to add 5-cycles.
    import itertools
    for c in itertools.combinations(range(n), 5):
        for p in itertools.permutations(c):
            # to avoid duplicates, only consider permutations where p[0] is min, and p[1] < p[4]
            if p[0] == min(p) and p[1] < p[4]:
                s.add(Not(And(E[p[0]][p[1]], E[p[1]][p[2]], E[p[2]][p[3]], E[p[3]][p[4]], E[p[4]][p[0]])))

    print(s.check())

solve()

def moore_bound(d, g):
    if g % 2 == 0:
        k = g // 2
        return 2 * sum((d - 1)**i for i in range(k))
    else:
        k = (g - 1) // 2
        return 1 + d * sum((d - 1)**i for i in range(k))

print("Moore bound for d=4, g=6:", moore_bound(4, 6))

def check_moore():
    # Just to be absolutely certain, let's run a small SAT solver instance for a smaller case
    # e.g., d=3, g=6. Moore bound is 2 * (1 + 2 + 4) = 14.
    # Let's check if 13 is unsat.
    from z3 import Bool, Solver, Or, Not, And, Sum, If
    import itertools

    def solve_dg(n, d, g):
        E = [[Bool(f"e_{i}_{j}") for j in range(n)] for i in range(n)]
        s = Solver()
        for i in range(n):
            s.add(Not(E[i][i]))
            for j in range(i+1, n):
                s.add(E[i][j] == E[j][i])
        for i in range(n):
            s.add(Sum([If(E[i][j], 1, 0) for j in range(n)]) >= d)

        if g > 3:
            for c in itertools.combinations(range(n), 3):
                s.add(Not(And(E[c[0]][c[1]], E[c[1]][c[2]], E[c[2]][c[0]])))
        if g > 4:
            for c in itertools.combinations(range(n), 4):
                for p in itertools.permutations(c):
                    if p[0] == min(p) and p[1] < p[3]:
                        s.add(Not(And(E[p[0]][p[1]], E[p[1]][p[2]], E[p[2]][p[3]], E[p[3]][p[0]])))
        if g > 5:
            for c in itertools.combinations(range(n), 5):
                for p in itertools.permutations(c):
                    if p[0] == min(p) and p[1] < p[4]:
                        s.add(Not(And(E[p[0]][p[1]], E[p[1]][p[2]], E[p[2]][p[3]], E[p[3]][p[4]], E[p[4]][p[0]])))
        return s.check()

    print("d=3, g=6, n=13:", solve_dg(13, 3, 6))
    print("d=3, g=6, n=14:", solve_dg(14, 3, 6))

check_moore()
